static void mv(int n, const int32_t* ip, const int32_t* ix, const double* d, const double* x, double* y) {
    int i = 0;
    for (; i + 4 <= n; i += 4) {
        int32_t a0 = ip[i], a1 = ip[i+1], a2 = ip[i+2], a3 = ip[i+3], a4 = ip[i+4];
        int32_t l0 = a1-a0, l1 = a2-a1, l2 = a3-a2, l3 = a4-a3;
        int32_t m = l0; if (l1 < m) m = l1; if (l2 < m) m = l2; if (l3 < m) m = l3;
        double s0 = 0, s1 = 0, s2 = 0, s3 = 0;
        for (int32_t t = 0; t < m; t++) {
            s0 += d[a0+t]*x[ix[a0+t]]; s1 += d[a1+t]*x[ix[a1+t]];
            s2 += d[a2+t]*x[ix[a2+t]]; s3 += d[a3+t]*x[ix[a3+t]];
        }
        for (int32_t t = m; t < l0; t++) s0 += d[a0+t]*x[ix[a0+t]];
        for (int32_t t = m; t < l1; t++) s1 += d[a1+t]*x[ix[a1+t]];
        for (int32_t t = m; t < l2; t++) s2 += d[a2+t]*x[ix[a2+t]];
        for (int32_t t = m; t < l3; t++) s3 += d[a3+t]*x[ix[a3+t]];
        y[i] = s0; y[i+1] = s1; y[i+2] = s2; y[i+3] = s3;
    }
    for (; i < n; i++) { double s = 0; for (int32_t j = ip[i]; j < ip[i+1]; j++) s += d[j]*x[ix[j]]; y[i] = s; }
}

