          int n, const int32_t* indptr, const int32_t* indices, const double* data) {
    naupd_t f = (naupd_t)fptr;
    int* ido = (int*)((char*)st + 0x34);
    for (;;) {
        f(st, resid, v, n, ipntr, workd, workl);
