import numpy as np
def to_sell(A, h=8):
    n=A.shape[0]; ns=(n+h-1)//h
    ip=A.indptr; lens=np.diff(ip)
    lens_p=np.zeros(ns*h,dtype=np.int64); lens_p[:n]=lens
    w=lens_p.reshape(ns,h).max(1).astype(np.int32)
